// Get all incoming items
const allItems = $input.all();

let formattedLeads = [];

for (const item of allItems) {

  const data = item.json;
  const root = Array.isArray(data) ? data[0] : data;

  if (!root?.organic_results) continue;

  for (const result of root.organic_results) {

    // --- Extract Name ---
    let name = result.title || "";
    // Remove common suffixes like " - Google Scholar", " | MIT", " - ResearchGate"
    name = name.split(" - ")[0].split(" | ")[0].trim();

    // --- Extract University ---
    let university = "";
    const snippet = result.snippet || "";
    const titleFull = result.title || "";

    // Try to find university from title (e.g. "John Doe | MIT")
    if (titleFull.includes("|")) {
      university = titleFull.split("|")[1]?.trim() || "";
    } else if (titleFull.includes(" - ")) {
      const parts = titleFull.split(" - ");
      if (parts.length > 1) university = parts[1]?.trim() || "";
    }

    // Fallback: try to pull from snippet
    if (!university) {
      const uniMatch = snippet.match(/(?:University of [\w\s]+|[\w\s]+ University|[\w\s]+ Institute of [\w\s]+|MIT|Stanford|Carnegie Mellon|Cornell|Princeton|Harvard|Yale|Columbia|Caltech)/i);
      if (uniMatch) university = uniMatch[0].trim();
    }

    // --- Extract Email ---
    let email = "";
    const emailMatch = snippet.match(/verified email at ([\w.\-]+)/i);
    if (emailMatch) email = emailMatch[1];

    // --- Detect Scholar URL ---
    const link = result.link || "";
    let scholar_url = "";
    if (link.includes("scholar.google.com")) {
      scholar_url = link;
    } else if (snippet.toLowerCase().includes("scholar") || titleFull.toLowerCase().includes("scholar")) {
      scholar_url = link; // best guess
    }

    // --- Extract Department ---
    let department = "";
    const deptMatch = snippet.match(/(?:Department|Dept\.?|School) of [A-Z][\w\s]+/i);
    if (deptMatch) department = deptMatch[0].trim();

    formattedLeads.push({
      name: name,
      full_title: result.title || "",
      university: university,
      department: department,
      email: email,
      scholar_url: scholar_url,
      profile_url: link,
      snippet: snippet,
      research_field: $('On form submission').first().json['Research Field'] || "",
      country: $('On form submission').first().json['Country or Region'] || "",
      source: result.source || ""
    });
  }
}

return formattedLeads.map(lead => ({ json: lead }));

const allItems = $input.all();
const results = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i];
  const data = item.json;

  const profItem = $('Code in JavaScript1').all()[i];
  const scholar_url = profItem?.json?.scholar_url || "";
  const profile_url = profItem?.json?.profile_url || "";
  const research_field = profItem?.json?.research_field || "";
  const country = profItem?.json?.country || "";

  const author = data.author || {};

  const name = author.name || profItem?.json?.name || "";
  const affiliations = author.affiliations || "";

  // Split "Professor, Santa Fe Institute" into title and university
  const affParts = affiliations.split(",").map(s => s.trim());
  const university = affParts.length > 1 ? affParts[1] : affParts[0];
  const job_title = affParts.length > 1 ? affParts[0] : "";

  // Clean email — "Verified email at santafe.edu" → "santafe.edu"
  const rawEmail = author.email || "";
  const emailMatch = rawEmail.match(/verified email at ([\w.\-]+)/i);
  const email = emailMatch ? emailMatch[1] : rawEmail;

  // Interests as comma separated string
  const interests = (author.interests || []).map(i => i.title).join(", ");

  // Citation stats
  const citedBy = data.cited_by?.table?.[0]?.citations?.all || "";
  const hIndex = data.cited_by?.table?.[1]?.h_index?.all || "";

  results.push({
    json: {
      name,
      university,
      job_title,
      email,
      interests,
      cited_by: citedBy,
      h_index: hIndex,
      scholar_url,
      profile_url,
      research_field,
      country
    }
  });
}

return results;
